      "cluster_id": "cl_routine_vs_variety",
      "label": "Tension Between Familiar Routines and Variety in Socializing",
      "definition": "Explores the balance or conflict between the comfort and predictability of established social routines and locations versus the desire for variety, flexible planning, and new experiences to prevent stagnation."
    },
    {
      "cluster_id": "cl_intentional_socializing",
      "label": "Shift Toward Intentional and Activity-Based Socializing",
      "definition": "Captures how social gatherings evolve, particularly with age, from passive drinking routines toward more structured, low-pressure activities and shared tasks that facilitate deeper, more meaningful conversations."
    },
    {
      "cluster_id": "cl_community_visibility",
      "label": "Social Dynamics of Community Visibility and Anonymity",
      "definition": "Focuses on the trade-offs of community environments, contrasting the support and practical security of local embeddedness with the social expectations, judgment, or desire for city-like anonymity."
    },
    {
      "cluster_id": "cl_gendered_dietary_policing",
      "label": "Masculinity and Social Policing of Dietary Choices",
      "definition": "Examines how meat-eating is linked to masculinity within male friend groups, leading to teasing, social pressure, and scrutiny when individuals deviate from the norm by choosing vegetarian options."
    },
    {
      "cluster_id": "cl_food_consciousness_quality",
      "label": "Growing Food Consciousness and Quality Preferences",
      "definition": "Addresses the shift in how men view food as they age, emphasizing an increased attention to sourcing, high-quality ingredients, and healthier, more conscious dietary choices."
    }
