{
  "clusters": [
    {
      "cluster_id": "routines_and_habitual_comfort",
      "label": "Defaulting to Familiar Routines and Habitual Comfort",
      "definition": "This cluster explores the comfort of adhering to familiar, unthinking daily routines and established habits for food and socializing, which simplify life by eliminating the need for constant, active decision-making."
    },
    {
      "cluster_id": "geographical_environmental_constraints",
      "label": "Geographical Influences and Environmental Constraints on Choice",
      "definition": "This cluster covers how geographical locations, physical distance, and rural versus urban settings impose structural constraints that shape social habits, meal planning, and food sourcing."
    },
    {
      "cluster_id": "local_sourcing_vs_convenience",
      "label": "Local Sourcing, Independent Retailers, and the Tension with Convenience",
      "definition": "This cluster captures the values of sourcing food from local independent shops and tradespeople to build community connections, contrasted against the daily ease, convenience, and financial practicality of using large supermarkets."
    },
    {
      "cluster_id": "domestic_dynamics_and_partnerships",
      "label": "Domestic Dynamics, Partnerships, and Life Transitions in Meal Planning",
      "definition": "This cluster examines how household relationships, gender roles, and major life changes (such as retirement, bereavement, or parenthood) shape the planning, preparation, and mental load of daily meal routines."
    },
    {
      "cluster_id": "dietary_choices_and_meat_consumption",
      "label": "Dietary Choices, Meat Consumption, and Shifts Toward Plant-Based Eating",
      "definition": "This cluster addresses attitudes toward meat consumption and reduction, including the health, ethical, and financial motivations behind dietary shifts, and the personal preferences or social pushback surrounding these choices."
    },
    {
      "cluster_id": "social_connection_and_community",
      "label": "Social Connection, Shared Meals, and Community Spaces",
      "definition": "This cluster highlights the value of gathering, shared family meals, and local social hubs like pubs in fostering genuine human connection, contrasted with the isolation of eating alone or transactional digital experiences."
    },
    {
      "cluster_id": "gendered_dietary_norms",
      "label": "Gendered Social Pressure and Dietary Norms among Men",
      "definition": "This cluster covers how social environments, such as pubs, and peer interactions, like banter, create and reinforce traditional dietary expectations and norms for men."
    },
    {
      "cluster_id": "decision_paralysis_and_choice_anxiety",
      "label": "Decision Paralysis and the Anxiety of Abundant Choice",
      "definition": "This cluster examines how an overwhelming abundance of choices, particularly through isolated digital ordering apps or unstructured environments, leads to overthinking, decision paralysis, and anxiety."
    },
    {
      "cluster_id": "food_awareness_vs_behavior_change",
      "label": "Food Awareness and the Gap Between Recognition and Behavior Change",
      "definition": "This cluster covers the awareness of one's own eating habits and cultural conditioning, emphasizing that recognizing these patterns or having fleeting moments of conscious reflection does not automatically translate into behavioral change."
    }
  ],
