{
  "clusters": [
    {
      "cluster_id": "agency_vs_social_conditioning",
      "label": "Individual agency versus social conditioning in dietary choices",
      "definition": "This cluster explores the ongoing tension between personal agency and social expectations, debating whether individual dietary choices and preferences are genuinely independent or if they are subtly directed, filtered, and internalized from social pressures and peer conformity."
    },
    {
      "cluster_id": "politicization_of_dietary_choices",
      "label": "Dietary choices as loaded moral or political statements",
      "definition": "This cluster addresses the social polarization and discomfort that occur when food choices, such as eating meat or adopting a vegetarian diet, are viewed as loaded moral or political statements rather than simple, unpoliticized personal preferences."
    },
    {
      "cluster_id": "masculine_norms_and_cooking_expectations",
      "label": "Masculinity, social expectations, and cooking behaviors",
      "definition": "This cluster examines the gendered social expectations of men regarding food, focusing on norms of masculine nonchalance, the lack of expectations to cook, and the tension between perceived independence and a practical reliance on partners or convenience."
    },
    {
      "cluster_id": "men_cooking_agency_in_later_life",
      "label": "Reclaiming cooking agency and self-care in later life",
      "definition": "This cluster highlights men's capacity and shift toward cooking and self-care as life transitions like aging or retirement loosen rigid masculine norms, enabling more active engagement in food preparation."
    },
    {
      "cluster_id": "convenience_and_illusion_of_choice",
      "label": "Convenience, routine defaults, and the illusion of choice",
      "definition": "This cluster focuses on how the availability of easy convenience foods and established social routines lead to mindless defaulting, bypassing active effort and rendering the abundance of food choices mostly theoretical."
    },
    {
      "cluster_id": "complicity_and_passive_self_awareness",
      "label": "Addressing complicity, passive reflectiveness, and active change",
      "definition": "This cluster deals with the realization of complicity or guilt in maintaining restrictive dining norms or systemic losses, highlighting the trap of performative self-awareness and the value of taking small, incremental actions to break passive patterns."
    }
  ],
