{
  "clusters": [
    {
      "cluster_id": "social_defaults_and_preference",
      "label": "Dietary Preferences Shaped by Social Defaults and Environment",
      "definition": "Individual food preferences are deeply shaped by cultural defaults and environment, leading some to seek autonomy by actively rejecting these passive defaults."
    },
    {
      "cluster_id": "action_vs_intellectual_awareness",
      "label": "Gap Between Intellectual Awareness and Action",
      "definition": "There is a notable gap between intellectually understanding a choice or dynamic and actually taking action to change behavior, with some suggesting that physical action must precede feelings or analysis."
    },
    {
      "cluster_id": "plant_based_culinary_identity",
      "label": "Plant-Based Food as a Distinct, High-Quality Category",
      "definition": "Plant-based options are most appealing when they are delicious on their own terms and treated as a distinct, high-quality culinary category rather than poor imitations of meat."
    },
    {
      "cluster_id": "visibility_and_environmental_availability",
      "label": "Environmental Visibility and Availability as Determinants of Choice",
      "definition": "The options available and visible in a person's immediate environment dictate whether alternative lifestyles are even perceived as viable choices."
    },
    {
      "cluster_id": "friction_and_costs_of_transition",
      "label": "Practical and Social Friction of Adopting Dietary Changes",
      "definition": "Transitioning to a plant-based diet involves significant, ongoing practical costs, mental load, and social friction, often requiring early adopters to bear a personal cost to normalize the choice."
    },
    {
      "cluster_id": "health_and_nutrition_considerations",
      "label": "Health and Nutritional Considerations of Plant-Based Diets",
      "definition": "Discussions surrounding plant-based diets involve weighing their health benefits, such as weight management, against nutritional concerns like meeting protein needs."
    },
    {
      "cluster_id": "identity_and_values_alignment",
      "label": "Alignment of Lifestyle Changes with Personal Identity and Values",
      "definition": "For lifestyle or dietary changes to be accepted, they must feel authentic and align with an individual's existing values and identity, rather than feeling forced or performative."
    },
    {
      "cluster_id": "resistance_to_moral_pressure",
      "label": "Resistance to Moral Pressure and Loaded Advocacy",
      "definition": "People react negatively to feeling judged, guilted, or pressured by advocacy, preferring positive messaging over loaded or accusatory terms like 'plant-based'."
    },
    {
      "cluster_id": "community_trust_and_social_proof",
      "label": "Role of Community Trust and Social Proof in Normalizing Choices",
      "definition": "The adoption and normalization of new food choices depend heavily on trusted personal networks, community ties, and social proof, such as trusted individuals preparing and sharing meals."
    }
  ],
